// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.facadeimport android.content.Contextimport com.roshan.persona.brain.skill.BrainSkillimport dagger.Bindsimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSetimport javax.inject.Singleton/** * NOUS — Productivity Skills Hilt Module (Module 14 v1.2 — Step 14.5). * * Binds: *   - 5 productivity skills (Alarm/Timer/Reminder/Note/Calendar) via `@Binds @IntoSet` multibinding. *   - [ProductivityFacade] (Singleton) — shared by all skills. *   - [ProductivityPermissionFlow] (Singleton) — for UI permission flows. * * ## Why a Singleton facade with Activity-scoped AlarmEngine? * * Per strategy v1.1 §"Shift 2", [AlarmEngine] is Activity-scoped (survives * rotation, not process death). The facade is a Singleton that holds * singleton instances of [com.roshan.persona.productivity.reminder.ReminderEngine], * [com.roshan.persona.productivity.note.NoteEngine], and * [com.roshan.persona.productivity.calendar.CalendarEngine]. * * For [AlarmEngine], the facade exposes `setAlarmEngine(engine)` — the * Activity registers its instance in `onResume` and clears it in `onPause`. * This avoids leaking the Activity while still letting the Singleton facade * call into the Activity-scoped alarm engine. * * ## Skill Registration * * Each `@Binds @IntoSet` adds one skill to Brain's `Set<BrainSkill>` multibinding. * Brain's [com.roshan.persona.brain.skill.registry.SkillRegistry] auto-discovers * all skills at app startup via this multibinding. */@Module@InstallIn(SingletonComponent::class)abstract class ProductivitySkillsModule {    @Binds @IntoSet    abstract fun bindAlarmSkill(impl: AlarmSkill): BrainSkill    @Binds @IntoSet    abstract fun bindTimerSkill(impl: TimerSkill): BrainSkill    @Binds @IntoSet    abstract fun bindReminderSkill(impl: ReminderSkill): BrainSkill    @Binds @IntoSet    abstract fun bindNoteSkill(impl: NoteSkill): BrainSkill    @Binds @IntoSet    abstract fun bindCalendarSkill(impl: CalendarSkill): BrainSkill}/** * Provides the singleton productivity facade + permission flow. * * ## Real DI wiring (audit fix) * * Previously, `ProductivityFacade` was created with `NoteEngine()` which * defaults to `InMemoryNoteStore` — notes were lost on process death. * * Now: we provide `RoomNoteStore` (backed by `NoteDao` + SQLCipher-encrypted * `EncryptedNoteDatabase`) + inject it into `NoteEngine`, which is then * injected into `ProductivityFacade`. Notes now persist across process death. */@Module@InstallIn(SingletonComponent::class)object ProductivityFacadeModule {    @Provides    @Singleton    fun provideEncryptedNoteDatabase(        @ApplicationContext context: Context,    ): com.roshan.persona.productivity.note.EncryptedNoteDatabase {        // Use a deterministic passphrase derived from app signing key.        // In production, this would use the user's app-lock PIN via Argon2.        val passphrase = com.roshan.persona.productivity.note.EncryptedNoteDatabase            .derivePassphrase(context)        return com.roshan.persona.productivity.note.EncryptedNoteDatabase.create(context, passphrase)    }    @Provides    @Singleton    fun provideNoteDao(        db: com.roshan.persona.productivity.note.EncryptedNoteDatabase,    ): com.roshan.persona.productivity.note.NoteDao = db.noteDao()    @Provides    @Singleton    fun provideNoteStore(        noteDao: com.roshan.persona.productivity.note.NoteDao,    ): com.roshan.persona.productivity.note.NoteStore =        com.roshan.persona.productivity.note.RoomNoteStore(noteDao)    @Provides    @Singleton    fun provideNoteEngine(        noteStore: com.roshan.persona.productivity.note.NoteStore,    ): com.roshan.persona.productivity.note.NoteEngine =        com.roshan.persona.productivity.note.NoteEngine(noteStore = noteStore)    @Provides    @Singleton    fun provideProductivityFacade(        @ApplicationContext context: Context,        noteEngine: com.roshan.persona.productivity.note.NoteEngine,    ): ProductivityFacade = ProductivityFacade(context = context, noteEngine = noteEngine)    @Provides    @Singleton    fun provideProductivityPermissionFlow(        @ApplicationContext context: Context,    ): ProductivityPermissionFlow = ProductivityPermissionFlow(context = context)}